// Anderson thermostat implementation
// Stochastically reassign velocities from Maxwell-Boltzmann distribution

// Use static random number generator for reproducibility
static std::mt19937 gen(std::random_device{}());
std::uniform_real_distribution<double> uniformDis(0.0, 1.0);

for (size_t i = 0; i < velocities.size(); ++i) {
    // Determine if this particle undergoes a velocity collision
    double collisionProbability = collisionFreq * dt;

    if (uniformDis(gen) < collisionProbability) {
        // Calculate standard deviation from Maxwell-Boltzmann distribution
        // v_std = sqrt(kB * T / m), using kB = 1 in reduced units
        double stdDev = std::sqrt(targetTemp / masses[i]);
        std::normal_distribution<double> normalDis(0.0, stdDev);

        // Sample new velocity components from normal distribution
        velocities[i].x = normalDis(gen);
        velocities[i].y = normalDis(gen);
        velocities[i].z = normalDis(gen);
    }
}

